   for(int i=0;i<10;i++){tool.State.cooldownRemaining=0;tool.BlowTap();}long bytesTotal=0,bytesPeak=0,ticksTotal=0,ticksPeak=0;var timer=new System.Diagnostics.Stopwatch();for(int i=0;i<100;i++){tool.State.cooldownRemaining=0;long before=GC.GetAllocatedBytesForCurrentThread();timer.Restart();tool.BlowTap();timer.Stop();long allocated=GC.GetAllocatedBytesForCurrentThread()-before;bytesTotal+=allocated;bytesPeak=Math.Max(bytesPeak,allocated);ticksTotal+=timer.ElapsedTicks;ticksPeak=Math.Max(ticksPeak,timer.ElapsedTicks);}string evidence="{\"samples\":100,\"meanBytes\":"+(bytesTotal/100d).ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"peakBytes\":"+bytesPeak+",\"meanMs\":"+(ticksTotal*1000d/System.Diagnostics.Stopwatch.Frequency/100).ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"peakMs\":"+(ticksPeak*1000d/System.Diagnostics.Stopwatch.Frequency).ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"scope\":\"Native school, warm synchronous BlowTap, actual HUD/pool/13 registered responders; cooldown bypassed only for measurement. Deferred responses, save I/O and whole-frame GPU excluded.\"}";File.WriteAllText("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/work/Whistle20261031/native-performance.json",evidence);}
